const item = $input.first();
const form = item.json;

return [
  {
    json: { source: 'linkedin', form },
    binary: { file: item.binary.LinkedIn_PDF }
  },
  {
    json: { source: 'clifton', form },
    binary: { file: item.binary.Clifton_PDF }
  },
  {
    json: { source: 'selfreflection', form },
    binary: { file: item.binary.SelfReflection_PDF }
  }
];

// ── INPUT ASSUMPTIONS ──────────────────────────────────────────────────────
// items[0] = LinkedIn PDF extracted text
// items[1] = Clifton PDF extracted text
// items[2] = Self-Reflection PDF extracted text (Blocks 1–6)
// Form Trigger: 3 PDF uploads only — no dropdown fields needed

const linkedin_text = items[0].json.text || "";
const clifton_raw   = items[1].json.text || "";
const sr_raw        = items[2].json.text || "";

// ── CLIFTON: strip boilerplate tail ────────────────────────────────────────
const cliftonCutMarker = "What did you read that surprises you?";
const cliftonCutIndex  = clifton_raw.indexOf(cliftonCutMarker);
const clifton_clean    = cliftonCutIndex !== -1
  ? clifton_raw.slice(0, cliftonCutIndex).trim()
  : clifton_raw;

// ── SELF-REFLECTION: split into blocks ─────────────────────────────────────
function extractBlock(text, startMarker, endMarker) {
  const start = text.indexOf(startMarker);
  if (start === -1) return "";
  const end = endMarker
    ? text.indexOf(endMarker, start + startMarker.length)
    : text.length;
  return text.slice(start, end === -1 ? text.length : end).trim();
}

const selfreflection_block1 = extractBlock(sr_raw, "Block 1", "Block 2");
const selfreflection_block2 = extractBlock(sr_raw, "Block 2", "Block 3");
const selfreflection_block3 = extractBlock(sr_raw, "Block 3", "Block 4");
const selfreflection_block4 = extractBlock(sr_raw, "Block 4", "Block 5");
const selfreflection_block5 = extractBlock(sr_raw, "Block 5", "Block 6");
const selfreflection_block6 = extractBlock(sr_raw, "Block 6", null);

// ── BLOCK 6: extract structured search parameters ──────────────────────────
function extractAnswer(blockText, questionMarker) {
  const qIdx = blockText.indexOf(questionMarker);
  if (qIdx === -1) return "";
  const answerMarker = "ANSWER:";
  const aIdx = blockText.indexOf(answerMarker, qIdx);
  if (aIdx === -1) return "";
  const nextQ = blockText.indexOf("Q3", aIdx); // next question starts with Q3x
  const end = nextQ !== -1 ? nextQ : blockText.length;
  return blockText.slice(aIdx + answerMarker.length, end).trim();
}

// Q33 — Timeline
const timeline_raw = extractAnswer(selfreflection_block6, "Q33");
const timeline = timeline_raw.toLowerCase().includes("active")      ? "Active search"
  : timeline_raw.toLowerCase().includes("runway")                   ? "I have runway"
  : timeline_raw.toLowerCase().includes("stepping")                 ? "Stepping stone first"
  : timeline_raw || "";

// Q34 — Employment and contract preference
const employment_raw = extractAnswer(selfreflection_block6, "Q34");
const employment_preference = employment_raw.toLowerCase().includes("permanent")   ? "Permanent employed"
  : employment_raw.toLowerCase().includes("contract")                              ? "Contract / Fixed term employed"
  : employment_raw.toLowerCase().includes("freelance")                             ? "Freelance / Project based"
  : employment_raw.toLowerCase().includes("fractional")                            ? "Fractional / Part-time consulting"
  : employment_raw.toLowerCase().includes("open")                                  ? "Open to any"
  : employment_raw || "";

// Q35 — Willing to relocate
const relocate_raw = extractAnswer(selfreflection_block6, "Q35");
const willing_to_relocate = relocate_raw.toLowerCase().includes("yes")             ? "Yes — open to relocation"
  : relocate_raw.toLowerCase().includes("no")                                      ? "No — location fixed"
  : relocate_raw.toLowerCase().includes("possibly")                                ? "Possibly — depends on role"
  : relocate_raw || "";

// Q36 — Preferred locations (free text — take as-is)
const preferred_locations = extractAnswer(selfreflection_block6, "Q36");

// Q37 — Working mode
const working_mode_raw = extractAnswer(selfreflection_block6, "Q37");
const working_mode = working_mode_raw.toLowerCase().includes("remote")             ? "Remote"
  : working_mode_raw.toLowerCase().includes("hybrid")                              ? "Hybrid"
  : working_mode_raw.toLowerCase().includes("presential")                          ? "Presential"
  : working_mode_raw.toLowerCase().includes("open")                                ? "Open to any"
  : working_mode_raw || "";

// ── VALIDATION ─────────────────────────────────────────────────────────────
const warnings = [];
if (!linkedin_text)          warnings.push("linkedin_text is empty");
if (!clifton_clean)          warnings.push("clifton_clean is empty");
if (!selfreflection_block1)  warnings.push("selfreflection_block1 is empty");
if (!selfreflection_block2)  warnings.push("selfreflection_block2 is empty");
if (!selfreflection_block3)  warnings.push("selfreflection_block3 is empty");
if (!selfreflection_block4)  warnings.push("selfreflection_block4 is empty");
if (!selfreflection_block5)  warnings.push("selfreflection_block5 is empty");
if (!selfreflection_block6)  warnings.push("selfreflection_block6 is empty — Block 6 missing from PDF");
if (!timeline)               warnings.push("timeline could not be extracted from Block 6 Q33");
if (!employment_preference)  warnings.push("employment_preference could not be extracted from Block 6 Q34");
if (!willing_to_relocate)    warnings.push("willing_to_relocate could not be extracted from Block 6 Q35");
if (!preferred_locations)    warnings.push("preferred_locations could not be extracted from Block 6 Q36");
if (!working_mode)           warnings.push("working_mode could not be extracted from Block 6 Q37");

// ── OUTPUT ─────────────────────────────────────────────────────────────────
return [{
  json: {
    // Source texts
    linkedin_text,
    clifton_clean,
    selfreflection_block1,
    selfreflection_block2,
    selfreflection_block3,
    selfreflection_block4,
    selfreflection_block5,
    selfreflection_block6,
    // Structured search parameters extracted from Block 6
    timeline,
    employment_preference,
    willing_to_relocate,
    preferred_locations,
    working_mode,
    // Diagnostics
    _warnings: warnings.length > 0 ? warnings : null
  }
}];

const items = $input.all();

// ── LLM outputs with JSON mode ON ──────────────────────────────────────────
// The actual data is at items[x].json.message.content
// items[x].json alone contains the full n8n response wrapper (index, message, logprobs etc.)
const career_depth = items[0].json.message.content;
const strengths    = items[1].json.message.content;
const transition   = items[2].json.message.content;

// ── Assemble portrait ───────────────────────────────────────────────────────
// timeline, employment_preference and working_mode now come from
// Prompt 3 output (extracted from self-reflection Block 6)
// No dependency on Form Trigger fields
const portrait = {
  career_depth,
  strengths,
  transition
};

// ── Validation ──────────────────────────────────────────────────────────────
const warnings = [];
if (!career_depth?.career_arc_summary) warnings.push("career_depth missing or empty — check Prompt 1 output");
if (!strengths?.strengths_top5)        warnings.push("strengths missing or empty — check Prompt 2 output");
if (!transition?.transition_motivation) warnings.push("transition missing or empty — check Prompt 3 output");

return [{
  json: {
    candidate_portrait: portrait,   // object — NOT stringified
    _warnings: warnings.length > 0 ? warnings : null
  }
}];

const portrait = $('Assemble Candidate Portrait').first().json.candidate_portrait;
const matches = $input.first().json.message.content;

return [{
  json: {
    candidate_portrait: typeof portrait === 'string' ? portrait : JSON.stringify(portrait),
    kb_matches: typeof matches === 'string' ? matches : JSON.stringify(matches)
  }
}];

// ── INPUT ASSUMPTIONS ──────────────────────────────────────────────────────
// Sequential pipeline — one item arrives from Assemble Positioning JSON
// Report Sections output reached back to directly

const positioningRaw = $input.first().json.message.content;
const sectionsRaw    = $('Report Sections').first().json.message.content;

const positioning = typeof positioningRaw === 'object'
  ? positioningRaw
  : JSON.parse(positioningRaw);

const sections = typeof sectionsRaw === 'object'
  ? sectionsRaw
  : JSON.parse(sectionsRaw);

// ── MERGE — positioning keys win on collision ───────────────────────────────
const report = Object.assign({}, sections, positioning);

// ── VALIDATION ─────────────────────────────────────────────────────────────
const warnings = [];
if (!sections.who_you_are)                          warnings.push("who_you_are missing from Report Sections");
if (!sections.top_profiles)                         warnings.push("top_profiles missing from Report Sections");
if (!sections.swot)                                 warnings.push("swot missing from Report Sections");
if (!positioning.positioning_statement)             warnings.push("positioning_statement missing from Positioning and Strategy");
if (!positioning.elevator_pitch)                    warnings.push("elevator_pitch missing from Positioning and Strategy");
if (!positioning.unspoken_concern_response)         warnings.push("unspoken_concern_response missing from Positioning and Strategy");
if (!positioning.transition_strategy)               warnings.push("transition_strategy missing from Positioning and Strategy");
if (!positioning.transition_strategy?.need_now)     warnings.push("transition_strategy.need_now missing");
if (!positioning.transition_strategy?.have_runway)  warnings.push("transition_strategy.have_runway missing");
if (!positioning.transition_strategy?.part_time)    warnings.push("transition_strategy.part_time missing");
if (!positioning.next_steps)                        warnings.push("next_steps missing from Positioning and Strategy");
if (!positioning.next_steps?.day_1)                 warnings.push("next_steps.day_1 missing");
if (!positioning.next_steps?.day_7)                 warnings.push("next_steps.day_7 missing");
if (!positioning.next_steps?.day_30)                warnings.push("next_steps.day_30 missing");
if (!positioning.next_steps?.day_60)                warnings.push("next_steps.day_60 missing");
if (!positioning.next_steps?.day_90)                warnings.push("next_steps.day_90 missing");
if (!positioning.next_steps?.learning)              warnings.push("next_steps.learning missing");

return [{
  json: {
    report,
    _warnings: warnings.length > 0 ? warnings : null
  }
}];

// ── INPUT ──────────────────────────────────────────────────────────────────
const data = $input.first().json.report;

const portraitRaw = $('Assemble Candidate Portrait').first().json.candidate_portrait;
const matchesRaw  = $('Validate Profile Matching').first().json.message.content;

const portrait = typeof portraitRaw === 'string' ? JSON.parse(portraitRaw) : portraitRaw;
const matches  = typeof matchesRaw  === 'string' ? JSON.parse(matchesRaw)  : matchesRaw;

const strengths_top5 = portrait?.strengths?.strengths_top5 || [];
const concerns       = portrait?.transition?.concerns       || [];
const all_scores     = matches?.all_scores                  || [];

// ── HELPERS ────────────────────────────────────────────────────────────────
const safe = (val) => (val || '').toString().replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const list = (arr) => (arr || []).map(i => `<li>${safe(i)}</li>`).join('');
const safeList = (arr) => (arr || []).map(i => `<li>${safe(i)}</li>`).join('');

// ── STRENGTH CARDS ─────────────────────────────────────────────────────────
const strengthCard = (s) => `
  <div class="s-card">
    <div class="s-header">
      <span class="s-name">${safe(s.name)}</span>
      <span class="s-domain">${safe(s.domain)}</span>
    </div>
    <div class="s-rows">
      <div class="s-row">
        <span class="s-tag">Deploy now</span>
        <span class="s-text">${safe(s.deploy_now)}</span>
      </div>
      <div class="s-row">
        <span class="s-tag">Learn &amp; explain AI</span>
        <span class="s-text">${safe(s.use_to_learn)}</span>
      </div>
      <div class="s-row">
        <span class="s-tag">Watch out</span>
        <span class="s-text">${safe(s.develop)}</span>
      </div>
    </div>
  </div>`;

// ── WHO YOU ARE / REFRAME / WHAT MAKES YOU RARE ───────────────────────────
const whoYouAre = data.who_you_are || '';
const reframe   = data.career_reframe_narrative || '';
const rare      = data.what_makes_you_rare || [];

const rareItems = rare.map(r => `<li>${safe(r)}</li>`).join('');

const compassIntro = `
  ${whoYouAre ? `<h2>Who you are in the AI world</h2><p>${safe(whoYouAre)}</p>` : ''}
  ${reframe   ? `<h2>Your career reframe</h2><p>${safe(reframe)}</p>` : ''}
  ${rareItems ? `<h2>What makes you rare</h2><ul>${rareItems}</ul>` : ''}
`;
const ep = data.elevator_pitch || {};
const pitchSection = `
  <div class="pitch-box">
    <div class="pitch-flag">AI suggestion — make it yours</div>
    <p class="pitch-full">"${safe(ep.full_pitch)}"</p>
    <div class="pitch-parts">
      <div class="pitch-part"><span class="pitch-tag">I help</span><span class="pitch-val">${safe(ep.who)}</span></div>
      <div class="pitch-part"><span class="pitch-tag">do what</span><span class="pitch-val">${safe(ep.do_what)}</span></div>
      <div class="pitch-part"><span class="pitch-tag">so they can</span><span class="pitch-val">${safe(ep.so_they_can)}</span></div>
    </div>
    <p class="pitch-note">This is a starting point. The best elevator pitch is the one you genuinely own. Try saying it out loud — if it does not sound like you, change it until it does.</p>
  </div>`;

// ── BEST PROFILE ───────────────────────────────────────────────────────────
const top      = (data.top_profiles || [])[0] || {};
const top_gaps = matches?.top_matches?.[0]?.gaps || top.gaps || [];

const gapCards = top_gaps.map(g => `
  <div class="gap-card">
    <div class="gap-title">${safe(g.gap)}</div>
    <div class="gap-severity sev-${(g.severity||'minor').toLowerCase()}">${safe(g.severity)}</div>
    ${g.what_to_do ? `<div class="gap-section"><span class="gap-label">What to do</span><p>${safe(g.what_to_do)}</p></div>` : ''}
    <div class="gap-section"><span class="gap-label">How to talk about it</span><p>${safe(g.how_to_talk_about_it)}</p></div>
  </div>`).join('');

// ── ALL SCORES RANKED LIST ─────────────────────────────────────────────────
const sorted_scores = [...all_scores]
  .sort((a,b) => (b.final_total||0) - (a.final_total||0))
  .slice(1);

const rankRows = sorted_scores.map((p, i) => {
  const pct = Math.round(p.final_total||0);
  const capped = p.hard_constraint_applied
    ? `<span class="capped-note" title="${safe(p.hard_constraint_note||'')}">capped</span>` : '';
  return `
  <div class="rank-row">
    <span class="rank-num">${i+2}</span>
    <span class="rank-name">${safe(p.profile_name)}</span>
    <div class="rank-bar-wrap"><div class="rank-bar" style="width:${pct}%"></div></div>
    <span class="rank-score">${p.final_total}${capped}</span>
  </div>`;
}).join('');

// ── CONCERN CARDS ──────────────────────────────────────────────────────────
const concernCards = concerns.map(c => `
  <div class="concern-card">
    <p class="concern-text">"${safe(c.concern_text)}"</p>
    <div class="concern-strength">
      <span class="cs-label">Clifton strength to deploy</span>
      <span class="cs-value">${safe(c.clifton_strength_to_deploy)}</span>
    </div>
    ${(c.bridge_actions && c.bridge_actions.length) ? `
    <div class="bridge-section">
      <div class="bridge-header">Bridge the gap</div>
      ${c.bridge_actions.map(a => `
        <div class="bridge-action">
          <span class="bridge-strength">${safe(a.strengths_deployed)}</span>
          <span class="bridge-text">${safe(a.action)}</span>
        </div>`).join('')}
    </div>` : ''}
  </div>`).join('');

// ── SWOT ──────────────────────────────────────────────────────────────────
const swot = data.swot || {};

// ── ENERGY ────────────────────────────────────────────────────────────────
const ev = data.energy_vs_performance || {};

// ── TRANSITION STRATEGY ───────────────────────────────────────────────────
const ts = data.transition_strategy || {};
const recommended = ts.recommended_scenario || '';

const needNowFixed = [
  'Complete your Ironhack AI programme — finish strong, this is your credential',
  'Improve your best Ironhack project — make it portfolio-ready and client-facing',
  'Apply for 10 roles per week — treat your job search as a full-time job',
  'Pitch SMEs and SMBs in your existing network for a short freelance gig, pilot, or proof of concept'
];

const haveRunwayFixed = [
  'Build a portfolio from your Ironhack projects — document, polish, make them client-facing',
  'Complete your Ironhack CareerHack programme'
];

const scenarioCard = (key, icon) => {
  const s = ts[key] || {};
  const isRec = recommended === key;

  let items = [];
  if (key === 'need_now') {
    items = [...needNowFixed];
    if (s.free_action) items.push(s.free_action);
  } else if (key === 'have_runway') {
    items = [...haveRunwayFixed];
    if (Array.isArray(s.free_actions)) items = [...items, ...s.free_actions];
  } else {
    if (Array.isArray(s.free_actions)) items = [...s.free_actions];
  }

  return `
  <div class="scenario-card${isRec ? ' recommended' : ''}">
    ${isRec ? `<div class="rec-badge">Recommended for you</div>` : ''}
    <div class="scenario-header">
      <span class="scenario-icon">${icon}</span>
      <div>
        <div class="scenario-label">${safe(s.label || key)}</div>
        <div class="scenario-desc">${safe(s.description || '')}</div>
      </div>
    </div>
    <ul class="scenario-list">${items.map(i => `<li>${safe(i)}</li>`).join('')}</ul>
    <div class="scenario-swot">${safe(s.swot_rooting)}</div>
  </div>`;
};

// ── NEXT STEPS ────────────────────────────────────────────────────────────
const ns = data.next_steps || {};

const day1Content = `
  <p class="day-action">${safe(ns.day_1?.action)}</p>
  <p class="day-why">${safe(ns.day_1?.why)}</p>
  <p class="day-output">→ ${safe(ns.day_1?.output)}</p>`;

const day7Content = `
  <ul>${safeList(ns.day_7?.actions)}</ul>
  <p class="day-milestone">Milestone: ${safe(ns.day_7?.milestone)}</p>`;

const day30Content = `
  <ul>${safeList(ns.day_30?.actions)}</ul>
  <p class="day-milestone">Milestone: ${safe(ns.day_30?.milestone)}</p>`;

const day60Content = `
  <p class="day-obj">${safe(ns.day_60?.objective)}</p>
  <ul>${safeList(ns.day_60?.actions)}</ul>`;

const dayCard = (label, content, isDay1) => `
  <div class="day-card${isDay1 ? ' day1' : ''}">
    <div class="day-label">${label}</div>
    ${content}
  </div>`;

// ── CERTIFICATIONS ────────────────────────────────────────────────────────
const learning = ns.learning || {};
const certs    = learning.certifications || {};

const ironhackCerts = (certs.ironhack_priority || []).map(c => `
  <div class="cert-card">
    <span class="cert-priority">Priority certification</span>
    <div class="cert-name">${safe(c.name)}</div>
    <div class="cert-provider">${safe(c.provider)}</div>
    <p class="cert-why">${safe(c.why)}</p>
  </div>`).join('');

const otherCerts = (certs.other_by_area || []).map(c => `
  <div class="cert-card">
    <div class="cert-area">${safe(c.area)}</div>
    <div class="cert-options">${(c.options||[]).map(o => `<span class="cert-option">${safe(o)}</span>`).join('')}</div>
    <p class="cert-why">${safe(c.why)}</p>
  </div>`).join('');

// ── DEEP DIVE ─────────────────────────────────────────────────────────────
const readTypeLabel = (type) => {
  if (type === 'read_books')         return 'Books';
  if (type === 'read_articles')      return 'Articles';
  if (type === 'self_paced')         return 'Self Paced';
  if (type === 'build_your_own_lab') return 'Build Your Own Lab';
  return type;
};

const readTypeClass = (type) => `read-${(type||'read_books').replace(/_/g,'-')}`;

const deepDive = (learning.selective_reading || [])
  .sort((a,b) => (a.priority||99) - (b.priority||99))
  .map(r => `
  <div class="read-item">
    <span class="read-type ${readTypeClass(r.type)}">${readTypeLabel(r.type)}</span>
    <div class="read-body">
      <div class="read-title">${safe(r.title)}</div>
      <div class="read-why">${safe(r.why)}</div>
    </div>
  </div>`).join('');

// ── COPY PAYLOAD ──────────────────────────────────────────────────────────
const copyPayload = JSON.stringify({ candidate_portrait: portrait, profile_matches: matches }, null, 2);

// ── HTML ──────────────────────────────────────────────────────────────────
const html = `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>AI Career LaunchPad — Career Compass</title>
<link href="https://fonts.googleapis.com/css2?family=Comfortaa:wght@300;400;500;600;700&display=swap" rel="stylesheet">
<style>
*{box-sizing:border-box;margin:0;padding:0}
body{font-family:'Comfortaa',cursive;font-size:15px;line-height:1.75;color:#111;background:#fff}
.header{background:#000;color:#fff;padding:24px 48px;display:flex;align-items:flex-start;justify-content:space-between;border-bottom:3px solid #dc2626}
.logo{font-size:22px;font-weight:700;color:#dc2626;line-height:1.2}
.logo span{color:#fff}
.logo-tagline{font-size:11px;color:#555;font-weight:300;display:block;margin-top:2px}
.header-tag{font-size:12px;color:#888;background:#1a1a1a;padding:4px 12px;border-radius:20px;align-self:center}
.main{max-width:960px;margin:0 auto;padding:40px 24px 80px}
.tab-radio{display:none}
.tabs{display:flex;gap:4px;border-bottom:2px solid #e0e0e0;margin-bottom:32px}
.tab-label{padding:10px 20px;cursor:pointer;font-size:14px;font-weight:500;color:#888;border-radius:8px 8px 0 0;border:1px solid transparent;border-bottom:none;font-family:'Comfortaa',cursive;display:block;transition:all .15s}
.tab-label:hover{color:#333}
#t1:checked~.tabs label[for=t1],
#t2:checked~.tabs label[for=t2],
#t3:checked~.tabs label[for=t3],
#t4:checked~.tabs label[for=t4],
#t5:checked~.tabs label[for=t5]{color:#dc2626;border-color:#e0e0e0;border-bottom-color:#fff;background:#fff;font-weight:600}
.tab-content{display:none}
#t1:checked~.tab-contents #p1,
#t2:checked~.tab-contents #p2,
#t3:checked~.tab-contents #p3,
#t4:checked~.tab-contents #p4,
#t5:checked~.tab-contents #p5{display:block}
h2{font-size:17px;font-weight:600;color:#dc2626;margin-top:36px;margin-bottom:14px;padding-bottom:6px;border-bottom:1px solid #e0e0e0}
h3{font-size:15px;font-weight:600;color:#111;margin-top:24px;margin-bottom:10px}
h4{font-size:13px;font-weight:600;color:#dc2626;margin-top:12px;margin-bottom:4px}
p{margin-bottom:10px;color:#333;font-size:14px}
ul{padding-left:20px;margin-bottom:14px}
li{margin-bottom:6px;color:#333;font-size:14px}
strong{color:#000}
.note{color:#777!important;font-style:italic;font-size:13px}

/* Strength cards */
.s-card{border:1px solid #e0e0e0;border-radius:8px;padding:18px 20px;margin-bottom:12px;background:#fafafa}
.s-header{display:flex;align-items:center;gap:12px;margin-bottom:14px}
.s-name{font-size:15px;font-weight:600;color:#000}
.s-domain{font-size:12px;font-weight:400;color:#dc2626;background:#f5f5f5;border:1px solid #e0e0e0;padding:3px 10px;border-radius:6px}
.s-rows{display:flex;flex-direction:column;gap:8px}
.s-row{display:flex;gap:10px;font-size:14px;align-items:flex-start}
.s-tag{font-size:12px;font-weight:400;color:#dc2626;background:#fff;border:1px solid #dc2626;padding:3px 10px;border-radius:6px;white-space:nowrap;flex-shrink:0;margin-top:1px;min-width:130px;text-align:center}
.s-text{color:#333}

/* Pitch */
.pitch-box{border:2px solid #dc2626;border-radius:8px;padding:16px 20px;margin:16px 0;background:#fafafa;position:relative}
.pitch-flag{position:absolute;top:-11px;left:16px;background:#fff;font-size:11px;font-weight:600;color:#dc2626;padding:0 6px;letter-spacing:.05em;text-transform:uppercase}
.pitch-full{font-size:15px;font-weight:600;color:#000;border-left:4px solid #dc2626;padding-left:14px;margin-bottom:14px;line-height:1.5}
.pitch-parts{margin-bottom:12px}
.pitch-part{display:flex;gap:10px;margin-bottom:6px;font-size:14px;align-items:flex-start}
.pitch-tag{font-size:12px;font-weight:600;background:#dc2626;color:#fff;padding:3px 10px;border-radius:6px;white-space:nowrap;flex-shrink:0;width:90px;text-align:center;margin-top:1px}
.pitch-val{color:#333}
.pitch-note{font-size:13px;color:#777;font-style:italic}

/* Transparency */
.transparency{border:1px solid #d97706;border-radius:8px;padding:14px 20px;margin-bottom:20px;font-size:13px;color:#d97706;background:#fffbf0;display:flex;gap:.5rem;align-items:flex-start}

/* Card */
.card{border:1px solid #e0e0e0;border-radius:8px;padding:18px 20px;margin-bottom:12px;background:#fafafa}

/* Profile meta badges */
.profile-header{display:flex;align-items:center;gap:12px;margin-bottom:14px}
.profile-name{font-size:15px;font-weight:600;color:#000;flex:1}
.profile-score{font-size:13px;font-weight:600;background:#16a34a;color:#fff;padding:3px 10px;border-radius:6px}
.q-number{background:#dc2626;color:white;width:28px;height:28px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:13px;font-weight:700;flex-shrink:0}
.profile-meta{margin-bottom:12px}
.profile-meta-row{display:flex;gap:8px;align-items:flex-start;margin-bottom:8px;font-size:14px}
.meta-badge{font-size:12px;font-weight:600;background:#dc2626;color:#fff;padding:3px 10px;border-radius:6px;white-space:nowrap;flex-shrink:0;margin-top:1px}
.meta-text{color:#333}

/* Gaps */
.gap-card{border:1px solid #e0e0e0;border-radius:8px;padding:14px 16px;margin-bottom:10px;background:#fffbf0;border-left:3px solid #d97706}
.gap-title{font-size:14px;font-weight:600;color:#000;margin-bottom:6px}
.gap-severity{display:inline-block;padding:3px 10px;border-radius:6px;font-size:12px;font-weight:600;color:#fff;margin-bottom:8px}
.sev-critical{background:#dc2626}
.sev-significant{background:#d97706}
.sev-minor{background:#16a34a}
.gap-section{margin-top:6px}
.gap-label{font-size:12px;font-weight:600;color:#dc2626;text-transform:uppercase;letter-spacing:.05em;display:block;margin-bottom:3px}
.gap-section p{font-size:13px;color:#333;margin-bottom:4px}

/* Rank */
.rank-row{display:flex;align-items:center;gap:12px;background:#fafafa;border:1px solid #e0e0e0;border-radius:8px;padding:8px 14px;margin-bottom:6px}
.rank-num{font-size:13px;font-weight:600;color:#888;width:20px;text-align:right}
.rank-name{font-size:14px;color:#111;flex:0 0 220px}
.rank-bar-wrap{flex:1;height:6px;background:#f0f0f0;border-radius:3px;overflow:hidden}
.rank-bar{height:100%;border-radius:3px;background:#dc2626}
.rank-score{font-size:13px;font-weight:600;color:#dc2626;min-width:36px;text-align:right}
.capped-note{font-size:11px;color:#d97706;margin-left:4px}

/* Concerns */
.concern-card{border:1px solid #e0e0e0;border-radius:8px;padding:14px 16px;margin-bottom:10px;background:#fafafa;border-left:3px solid #dc2626}
.concern-text{font-size:14px;color:#333;font-style:italic;margin-bottom:8px}
.concern-strength{display:flex;gap:8px;align-items:flex-start;margin-bottom:10px}
.cs-label{font-size:12px;font-weight:600;background:#dc2626;color:#fff;padding:3px 10px;border-radius:6px;white-space:nowrap;flex-shrink:0;margin-top:1px}
.cs-value{font-size:13px;color:#333}
.bridge-section{margin-top:10px;border-top:1px solid #e0e0e0;padding-top:10px}
.bridge-header{font-size:12px;font-weight:600;background:#dc2626;color:#fff;padding:3px 10px;border-radius:6px;display:inline-block;margin-bottom:8px}
.bridge-action{display:flex;gap:8px;align-items:flex-start;margin-bottom:6px;font-size:13px}
.bridge-strength{font-size:11px;font-weight:600;background:#fff;border:1px solid #dc2626;color:#dc2626;padding:2px 8px;border-radius:6px;white-space:nowrap;flex-shrink:0;margin-top:1px}
.bridge-text{color:#333}

/* SWOT */
.swot-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-bottom:24px}
.swot-card{border-radius:8px;padding:16px;border:1px solid}
.swot-s{background:#f0fdf4;border-color:#86efac;color:#14532d}
.swot-w{background:#fef2f2;border-color:#fca5a5;color:#7f1d1d}
.swot-o{background:#eff6ff;border-color:#93c5fd;color:#1e3a5f}
.swot-t{background:#fffbeb;border-color:#fcd34d;color:#78350f}
.swot-card h4{font-size:13px;font-weight:600;text-transform:uppercase;letter-spacing:.05em;margin-bottom:8px}
.swot-card ul{font-size:13px;padding-left:18px}
.swot-card li{margin-bottom:4px}

/* Energy */
.energy-grid{display:grid;grid-template-columns:1fr 1fr 1fr;gap:16px;margin-bottom:16px}
.energy-card{border:1px solid #e0e0e0;border-radius:8px;padding:16px;background:#fafafa}
.energy-green{border-left:3px solid #16a34a}
.energy-green h4{color:#16a34a}
.energy-orange{border-left:3px solid #d97706}
.energy-orange h4{color:#d97706}
.energy-neutral{border-left:3px solid #888}
.energy-neutral h4{color:#555}

/* Scenario */
.scenario-card{border:1px solid #e0e0e0;border-radius:8px;padding:18px 20px;margin-bottom:12px;background:#fafafa}
.scenario-card.recommended{border:2px solid #dc2626;background:#fff}
.rec-badge{display:inline-block;padding:3px 12px;border-radius:6px;font-size:12px;font-weight:600;background:#dc2626;color:#fff;margin-bottom:10px}
.scenario-header{display:flex;align-items:center;gap:12px;margin-bottom:10px}
.scenario-icon{width:32px;height:32px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:14px;font-weight:700;flex-shrink:0;background:#dc2626;color:#fff}
.scenario-label{font-size:15px;font-weight:600;color:#000}
.scenario-desc{font-size:12px;color:#888}
.scenario-list{padding-left:20px;margin-bottom:10px}
.scenario-list li{font-size:14px;color:#333;margin-bottom:6px}
.scenario-swot{font-size:13px;color:#777;font-style:italic;border-top:1px solid #e0e0e0;padding-top:10px;margin-top:6px}

/* Day cards */
.next-steps-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-bottom:24px}
.day-card{border:1px solid #e0e0e0;border-radius:8px;padding:16px;background:#fafafa}
.day-card.day1{grid-column:1/-1;border-top:3px solid #dc2626}
.day-label{font-size:12px;font-weight:600;color:#dc2626;text-transform:uppercase;letter-spacing:.06em;margin-bottom:8px}
.day-action{font-size:14px;font-weight:600;color:#000;margin-bottom:6px}
.day-why{font-size:13px;color:#555;margin-bottom:6px}
.day-output{font-size:13px;color:#16a34a;font-weight:600}
.day-obj{font-size:14px;font-weight:600;color:#000;margin-bottom:8px}
.day-milestone{font-size:12px;color:#dc2626;font-style:italic;margin-top:8px}
.day-card ul{padding-left:18px;margin-bottom:0}
.day-card li{font-size:13px;color:#333;margin-bottom:4px}

/* CTA */
.cta-box{background:#000;border-radius:8px;padding:1rem 1.25rem;margin-bottom:1.25rem;display:flex;align-items:center;justify-content:space-between;gap:1rem;flex-wrap:wrap}
.cta-box p{font-size:.88rem;color:#fff;font-weight:500}
.cta-btn{font-size:13px;font-weight:600;background:#dc2626;color:#fff;border:none;padding:8px 20px;border-radius:6px;cursor:pointer}

/* Certs */
.cert-row{display:flex;gap:12px;flex-wrap:wrap;margin-bottom:16px}
.cert-card{border:1px solid #e0e0e0;border-radius:8px;padding:14px 16px;flex:1;min-width:180px;background:#fafafa}
.cert-priority{font-size:12px;font-weight:600;background:#dc2626;color:#fff;padding:3px 10px;border-radius:6px;display:inline-block;margin-bottom:8px}
.cert-name{font-size:14px;font-weight:600;color:#000;margin-bottom:2px}
.cert-provider{font-size:12px;color:#888;margin-bottom:6px}
.cert-why{font-size:12px;color:#555}
.cert-area{font-size:13px;font-weight:600;color:#dc2626;margin-bottom:6px}
.cert-options{margin-bottom:6px}
.cert-option{font-size:12px;background:#f0f0f0;color:#333;padding:3px 8px;border-radius:6px;display:inline-block;margin-bottom:3px}

/* Deep Dive */
.read-item{display:flex;gap:12px;padding:10px 0;border-bottom:1px solid #e0e0e0;align-items:flex-start}
.read-item:last-child{border-bottom:none}
.read-type{font-size:12px;font-weight:600;padding:3px 10px;border-radius:6px;white-space:nowrap;flex-shrink:0;margin-top:2px;min-width:110px;text-align:center}
.read-read-books{background:#dc2626;color:#fff}
.read-read-articles{background:#dc2626;color:#fff}
.read-self-paced{background:#fff;color:#dc2626;border:1px solid #dc2626}
.read-build-your-own-lab{background:#f5f5f5;color:#dc2626}
.read-title{font-size:14px;font-weight:600;color:#000;margin-bottom:2px}
.read-why{font-size:12px;color:#555}

/* Copy */
.copy-section{margin-top:32px;border:1px solid #e0e0e0;border-radius:8px;padding:24px;background:#fafafa}
.copy-section h3{margin-top:0;color:#000;margin-bottom:8px;font-size:15px;font-weight:600}
.copy-section p{color:#666;font-size:13px;margin-bottom:12px}
textarea{width:100%;height:160px;margin-top:8px;background:#f5f5f5;color:#333;border:1px solid #e0e0e0;border-radius:6px;padding:14px;font-family:monospace;font-size:12px;resize:vertical}
.footer{margin-top:48px;text-align:center;font-size:12px;color:#aaa;padding-bottom:40px}
</style>
</head>
<body>

<div class="header">
  <div class="logo">AI Career <span>LaunchPad</span><em class="logo-tagline">Your experience got you here. LaunchPad gets you there.</em></div>
  <div class="header-tag">Career Compass Report</div>
</div>

<div class="main">

  <input type="radio" name="tabs" id="t1" class="tab-radio" checked>
  <input type="radio" name="tabs" id="t2" class="tab-radio">
  <input type="radio" name="tabs" id="t3" class="tab-radio">
  <input type="radio" name="tabs" id="t4" class="tab-radio">
  <input type="radio" name="tabs" id="t5" class="tab-radio">

  <div class="tabs">
    <label class="tab-label" for="t1">Your Compass</label>
    <label class="tab-label" for="t2">Your Best Profile</label>
    <label class="tab-label" for="t3">Your Reality Check</label>
    <label class="tab-label" for="t4">Your Move</label>
    <label class="tab-label" for="t5">Next Steps</label>
  </div>

  <div class="tab-contents">

    <!-- TAB 1 — YOUR COMPASS -->
    <div id="p1" class="tab-content">
      ${compassIntro}
      <h2>Your Clifton Strengths — deployed for this transition</h2>
      ${strengths_top5.map(s => strengthCard(s)).join('')}
      <h2>Your Elevator Pitch — 10 seconds to grab attention</h2>
      ${pitchSection}
    </div>

    <!-- TAB 2 — YOUR BEST PROFILE -->
    <div id="p2" class="tab-content">
      <div class="transparency">&#9888; <div><strong>Transparency notice &middot; Produced with AI.</strong> This profile match is generated by an AI system based on your inputs. It is a starting point for reflection, not a definitive career verdict. Use your own judgement.</div></div>
      <h2>Your Best-Fit Profile</h2>
      <div class="card">
        <div class="profile-header">
          <div class="q-number">${safe((top.profile_name||'').split(' ').map(w=>w[0]).slice(0,2).join(''))}</div>
          <div class="profile-name">${safe(top.profile_name)}</div>
          <div class="profile-score">${top.total_score || top.final_total || ''}% fit</div>
        </div>
        <div class="profile-meta">
          <div class="profile-meta-row"><p>${safe(top.why_this_fits)}</p></div>
          <div class="profile-meta-row"><span class="meta-badge">What you bring</span><span class="meta-text">${safe(top.what_you_bring)}</span></div>
          <div class="profile-meta-row"><span class="meta-badge">Your angle</span><span class="meta-text">${safe(top.positioning_angle)}</span></div>
          <div class="profile-meta-row"><span class="meta-badge">Anchor alignment</span><span class="meta-text">${safe(top.career_anchor_alignment_note)}</span></div>
          <div class="profile-meta-row"><span class="meta-badge">Working style fit</span><span class="meta-text">${safe(top.working_style_fit_note)}</span></div>
        </div>
        <h4>Gaps — what to do &amp; how to talk about them</h4>
        ${gapCards}
      </div>
      <h2>Other Profiles — Ranked</h2>
      <div class="rank-list">${rankRows}</div>
    </div>

    <!-- TAB 3 — YOUR REALITY CHECK -->
    <div id="p3" class="tab-content">
      <h2>Energy vs Performance</h2>
      <div class="energy-grid">
        <div class="card energy-green"><h4>High energy + High performance</h4><ul>${list(ev.high_energy_high_performance)}</ul></div>
        <div class="card energy-orange"><h4>High performance + Low energy</h4><ul>${list(ev.high_performance_low_energy)}</ul></div>
        <div class="card energy-neutral"><h4>High energy + Still developing</h4><ul>${list(ev.high_energy_developing)}</ul></div>
      </div>
      <p class="note">${safe(ev.role_targeting_implication)}</p>
      <h2>The Concerns You Named — Addressed</h2>
      ${concernCards}
      <h2>SWOT Analysis</h2>
      <div class="swot-grid">
        <div class="swot-card swot-s"><h4>Strengths</h4><ul>${list(swot.strengths)}</ul></div>
        <div class="swot-card swot-w"><h4>Weaknesses</h4><ul>${list(swot.weaknesses)}</ul></div>
        <div class="swot-card swot-o"><h4>Opportunities</h4><ul>${list(swot.opportunities)}</ul></div>
        <div class="swot-card swot-t"><h4>Threats</h4><ul>${list(swot.threats)}</ul></div>
      </div>
    </div>

    <!-- TAB 4 — YOUR MOVE -->
    <div id="p4" class="tab-content">
      <h2>Your Transition Strategy</h2>
      <p class="note">${safe(ts.recommended_rationale)} All three paths are shown — your recommended path is highlighted.</p>
      ${scenarioCard('need_now', '⚡')}
      ${scenarioCard('have_runway', '▲')}
      ${scenarioCard('part_time', '◑')}
    </div>

    <!-- TAB 5 — NEXT STEPS -->
    <div id="p5" class="tab-content">
      <div class="cta-box">
        <p>Day 1 action: Sign up as an Alpha Tester for AI Career LaunchPad</p>
        <button class="cta-btn" onclick="alert('Alpha tester sign-up — coming soon!')">Sign up as alpha tester &rarr;</button>
      </div>
      <h2>Your Next Steps</h2>
      <p class="note">${safe(ns.calibration_note)}</p>
      <div class="next-steps-grid">
        ${dayCard('Day 1', day1Content, true)}
        ${dayCard('Day 7', day7Content, false)}
        ${dayCard('Day 30', day30Content, false)}
        ${dayCard('Day 60', day60Content, false)}
      </div>
      <div style="border:2px solid #dc2626;border-radius:8px;padding:16px 20px;background:#fafafa;margin-bottom:24px">
        <div class="day-label">Day 90</div>
        <p class="day-obj">${safe(ns.day_90?.objective)}</p>
        <ul>${safeList(ns.day_90?.actions)}</ul>
      </div>
      <h2>Certifications</h2>
      <p class="note">Add one domain-specific certification as a complement.</p>
      <div class="cert-row">${ironhackCerts}</div>
      <div class="cert-row">${otherCerts}</div>
      <h2>Deep Dive</h2>
      ${deepDive}
      <div class="copy-section">
        <h3>Ready to apply for a role?</h3>
        <p>Click inside the box, select all, copy. Paste into the Application Engine (WF3).</p>
        <textarea onclick="this.select()" readonly>${copyPayload.replace(/</g,'&lt;').replace(/>/g,'&gt;')}</textarea>
        <p style="margin-top:8px;font-size:12px;color:#aaa">Click the box to select all, then copy.</p>
      </div>
    </div>

  </div>
</div>

<div class="footer">
  <p>Generated by AI Career LaunchPad &bull; Session data not stored after this page closes</p>
</div>

<script>
  document.getElementById('compass-data') && document.getElementById('compass-data').addEventListener('click', function(){ this.select(); });
<\/script>

</body>
</html>`;

return [{ json: { html } }];

// ── INPUT ASSUMPTIONS ──────────────────────────────────────────────────────
// This node receives output from LLM — Report Sections
// It reaches back to Prepare Report Inputs for portrait and kb_matches
// which are already serialised strings

// Report sections from LLM — Report Sections output
const report_sections = $input.first().json.message.content;

// Portrait and kb_matches already serialised strings from Prepare Report Inputs
const candidate_portrait = $('Prepare Report Inputs').first().json.candidate_portrait;
const kb_matches         = $('Prepare Report Inputs').first().json.kb_matches;

// ── VALIDATION ─────────────────────────────────────────────────────────────
const warnings = [];
if (!candidate_portrait) warnings.push("candidate_portrait is empty");
if (!kb_matches)          warnings.push("kb_matches is empty");
if (!report_sections)     warnings.push("report_sections is empty — check LLM Report Sections output");

// ── OUTPUT ─────────────────────────────────────────────────────────────────
return [{
  json: {
    candidate_portrait: typeof candidate_portrait === 'string'
      ? candidate_portrait
      : JSON.stringify(candidate_portrait),
    kb_matches: typeof kb_matches === 'string'
      ? kb_matches
      : JSON.stringify(kb_matches),
    report_sections: typeof report_sections === 'string'
      ? report_sections
      : JSON.stringify(report_sections),
    _warnings: warnings.length > 0 ? warnings : null
  }
}];

values.content:
=Analyse the LinkedIn profile and self-reflection answers below. Extract a structured career depth portrait using the exact JSON schema provided.
The self-reflection is Block 1 only — questions about career depth, domain expertise, problem types, prior AI-adjacent work, signature achievements, and subject matter interest.

LINKEDIN PROFILE:
{{ $json.linkedin_text }}

SELF-REFLECTION — BLOCK 1 (Career Depth):
{{ $json.selfreflection_block1 }}

Return this exact JSON structure. All fields are required. Use arrays where indicated. Use null only if a field genuinely cannot be determined from the available text.
{
"career_arc_summary": "string — one paragraph describing the shape of the career as a whole: where it started, where it pivoted, and where it is heading. Derived from LinkedIn chronology only. This is pattern extraction, not narrative generation. Name the actual roles and transitions.",
"domain_expertise": {
"primary_domain": "string — the candidate's deepest area of professional expertise, as evidenced by years, seniority and recurrence across LinkedIn roles",
"secondary_domains": ["string — each secondary domain with brief description, evidenced on LinkedIn"],
"years_experience": "string — total years of professional experience derived from LinkedIn dates",
"industry_contexts": ["string — each industry or sector evidenced on LinkedIn"],
"technical_depth": "string — specific technical skills and knowledge evidenced on LinkedIn. Not aspirational. Not from self-reflection only."
},
"transferable_skills": [
{
"skill": "string — specific skill name",
"evidence": "string — one concrete example from LinkedIn or self-reflection. Name the role or context.",
"source": "string — one of: linkedin | self_reflection | both",
"ai_consulting_relevance": "string — how this maps directly to AI consulting work"
}
],
"ai_narrative_anchors": [
{
"anchor": "string — a specific role, project or moment where the candidate was doing something adjacent to AI: data, optimisation, decision logic, automation, pattern recognition, predictive systems, neural networks, rule-based systems",
"description": "string — factual description of what they actually did. Name the employer, role and output.",
"source": "string — one of: linkedin | self_reflection | both",
"reframe_potential": "string — how this moment can be positioned in an AI consulting narrative"
}
],
"signature_achievements": [
{
"what": "string — what they achieved in concrete terms",
"context": "string — the scale, setting and constraints. Numbers where available.",
"skills_demonstrated": ["string — specific skills this achievement demonstrates"],
"source": "string — one of: linkedin | self_reflection | both",
"ai_consulting_signal": "string — what this achievement signals about their readiness for AI consulting work",
"rank": "number — 1 is most relevant to AI consulting, not most personally significant"
}
],
"differentiators": [
"string — each differentiator must name the specific combination: domain + context + capability. Generic strengths are not differentiators. 'Strong communicator' is not a differentiator. 'Safety-critical systems engineer who built a 5000-user global learning platform and applied neural networks in 1997' is. Maximum 5. Minimum 3."
],
"subject_matter_wants_more": {
"topics": ["string — subject areas the candidate explicitly stated they want more of in Block 1 Q6"],
"activities": ["string — types of work they explicitly said they want to be doing"],
"source": "string — self_reflection Block 1 Q6"
}
}
EXTRACTION RULES:

ai_narrative_anchors: extract ALL anchors present in the data. Minimum 3 if the evidence supports it. Do not stop at the most obvious one.
signature_achievements: extract up to 3. Rank them by AI consulting relevance (rank 1 = most relevant), not by the candidate's stated pride or career chronology.
differentiators: every entry must name a specific combination. If you find yourself writing a generic skill, stop and rewrite it as a combination.
career_arc_summary: derived from LinkedIn dates and role titles only. Do not use self-reflection to construct this.

=Analyse the CliftonStrengths report and self-reflection answers below. Extract a structured strengths portrait using the exact JSON schema provided.
The self-reflection is Block 2 only — questions about working style, career anchors, group role, ambiguity tolerance, hard avoids, stakeholder comfort, competent-but-draining activities, and developing-but-energising activities.

CLIFTONSTRENGTHS REPORT:
{{ $json.clifton_clean }}

SELF-REFLECTION — BLOCK 2 (Working Style):
{{ $json.selfreflection_block2 }}

Return this exact JSON structure. All fields are required. Use arrays where indicated. Use null only if a field genuinely cannot be determined from the available text.

{
  "strengths_top5": [
    {
      "name": "string — strength name",
      "domain": "string — one of: Executing | Influencing | Relationship Building | Strategic Thinking",
      "personalised_insight": "string — what the Clifton report says specifically about how this strength shows up for this candidate. Use the Why Your X Is Unique section. Not the generic definition.",
      "deploy_now": "string — one specific, honest statement of how this strength gives the candidate a concrete edge right now: in the job search, repositioning, interviews, or first client conversations. Not a restatement of what the strength is. Name the specific advantage.",
      "use_to_learn": "string — how this strength helps the candidate learn AI concepts faster and explain them more clearly to non-technical clients and stakeholders. Specific to this strength — not consulting in general.",
      "develop": "string — where this strength becomes a liability during transition if unmanaged. Be direct and honest. Do not soften this. Name the specific risk."
    }
  ],
  "strengths_cluster": {
    "dominant_domain": "string — the CliftonStrengths domain that appears most in the top 5",
    "cluster_insight": "string — what the combination of these specific strengths reveals about how this candidate thinks, decides and operates. Reference the blend descriptions from the report. This is not a list of the strengths — it is what they produce together.",
    "cluster_transition_asset": "string — how the cluster as a whole helps during the transition. What does having this specific combination allow the candidate to do that a different combination would not.",
    "cluster_transition_risk": "string — what the cluster as a whole risks during transition. What is missing or underrepresented in this combination that could slow the search or create blind spots."
  },
  "career_anchors": {
    "top3": ["string — each anchor as stated in Block 2 Q7, in order"],
    "anchor_insight": "string — what this anchor combination reveals about what the candidate needs from work to feel fulfilled. Connect to the Clifton cluster where relevant.",
    "anchor_transition_signal": "string — what this anchor combination signals about which AI consulting archetypes will feel right and which will feel like a compromise"
  },
  "working_style": {
    "solo_vs_team": "string — how they do their best work, with evidence from Block 2",
    "group_role": "string — the role they naturally take in a group, with evidence from Block 2",
    "ambiguity_operating_style": "string — how they operate under genuine complexity and uncertainty, with evidence from Block 2",
    "stakeholder_comfort": "string — where they feel most credible and energised, with evidence from Block 2"
  },
  "energy_vs_performance": {
    "competent_but_draining": ["string — activities they are good at but that cost them energy, from Block 2 Q13"],
    "developing_but_energising": ["string — activities they are still building but that give them energy, from Block 2 Q14"],
    "transition_implication": "string — what this energy split means for which roles to target and which to avoid during this specific transition"
  },
  "hard_avoids": {
    "items": ["string — each hard avoid from Block 2 Q11"],
    "why_it_matters": "string — what the hard avoids reveal about cultural and structural fit requirements. Connect to Clifton and career anchors."
  }
}

EXTRACTION RULES:
- personalised_insight: use the Why Your X Is Unique section from the Clifton report. Not the What Is X generic definition. If you find yourself writing something that applies to everyone with this strength, stop and rewrite it.
- deploy_now: must name a specific advantage in this candidate's transition context. Not a restatement of what the strength is. If it could appear in any career report, rewrite it.
- use_to_learn: must connect this specific strength to AI learning or explanation. Not consulting in general.
- develop: must name a real, specific risk. A softened or reassuring develop field is a failure of this extraction.
- strengths_cluster.cluster_insight: reference the blend descriptions from the report — Futuristic + Ideation, Ideation + Strategic, etc. This field describes what the combination produces, not what each strength is.

