const p1 = typeof part1raw === 'object' ? part1raw : JSON.parse(part1raw);
const p2a = typeof part2araw === 'object' ? part2araw : JSON.parse(part2araw);
const p2b = typeof part2braw === 'object' ? part2braw : JSON.parse(part2braw);

const assembled = {
  positioning_statement:         p1.positioning_statement,
  elevator_pitch:                p1.elevator_pitch,
  unspoken_concern_response:     p1.unspoken_concern_response,
  presentation_development_note: p1.presentation_development_note,
  transition_strategy:           p2a.transition_strategy,
  next_steps:                    p2b.next_steps
};

const warnings = [];
if (!p1.positioning_statement)          warnings.push('positioning_statement missing from Part 1');
if (!p1.elevator_pitch)                 warnings.push('elevator_pitch missing from Part 1');
if (!p1.unspoken_concern_response)      warnings.push('unspoken_concern_response missing from Part 1');
if (!p1.presentation_development_note)  warnings.push('presentation_development_note missing from Part 1');
if (!p2a.transition_strategy)           warnings.push('transition_strategy missing from Part 2A');
